+        long now = 0;
+        for (int i = 0; i < cycles; i++) {
+            now += between(1, 100000);
+            sleeps = sleeps.sleep(randomSleepReason(), now);
+            if (i != cycles - 1 || randomBoolean()) {
+                // Randomly don't wake on the last sleep
