+            if (checkSums[blockIndex] != data.checkSums[blockIndex]) {
+                throw new AssertionError(
+                    "checksums do not match for block ["
+                        + blockIndex
+                        + "]["
+                        + dataType
+                        + "]["
+                        + blockKind
