+        finishedPlanning.add(spec);
+    }
+
+    private void addStep(InjectionStep newStep, int depth) {
+        logger.trace("{}- Add step {}", indent(depth), newStep);
+        plan.add(newStep);
+    }
+
+    private static Supplier<String> indent(int depth) {
+        return () -> "\t".repeat(depth);
+    }
+}

