+        SubmitAsyncSearchRequest request = new SubmitAsyncSearchRequest(indices);
+        request.setCcsMinimizeRoundtrips(randomBoolean());
+        request.setWaitForCompletionTimeout(TimeValue.timeValueMillis(1));
